    getProducts: {
        parameters: {
            query?: {
                /**
                 * @description Filter products by name (case-insensitive partial match)
                 * @example Product 1
                 */
                name?: string;
                /**
                 * @description Filter products by quantity type
                 * @example DEVICE_COUNTS
                 */
                quantityType?: string;
                /**
                 * @description Filter products by account code
                 * @example HARDWARE
                 */
                accountCode?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description List of products successfully retrieved */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * Format: int32
                         * @description Unique identifier of the product.
                         * @example 1
                         */
                        id?: number;
                        /**
                         * @description Name of the product.
                         * @example Hardware Support
                         */
                        name?: string;
                        /**
                         * @description Description of the product.
                         * @example Monthly hardware support service
                         */
                        description?: string;
                        /**
                         * @description Quantity type of the product.
                         * @example DEVICE_COUNTS
                         * @enum {string}
                         */
                        quantityType?: "MANUAL" | "DEVICE_COUNTS" | "TIME_ENTRIES" | "END_USER_COUNTS" | "BACKUP_STORAGE_COUNTS" | "SOFTWARE_LICENSE";
                        /** @description Additional content/configuration for the product. Structure varies by quantity type. Includes price, cost, taxable, and other type-specific fields. */
                        content?: Record<string, never>;
                        /**
                         * Format: double
                         * @description Timestamp when the product was created.
                         */
                        createTime?: number;
                        /**
                         * Format: double
                         * @description Timestamp when the product was last updated.
                         */
                        updateTime?: number;
                        /**
                         * Format: int32
                         * @description Account ID associated with the product.
                         * @example 8
                         */
                        accountId?: number;
                        /**
                         * @description Whether the product is a group product.
                         * @example false
                         */
                        group?: boolean;
                        /**
                         * Format: int32
                         * @description Tax ID associated with the product. Null if no specific tax is set.
                         * @example 1
                         */
                        taxId?: number | null;
                        /**
                         * @description Whether the product inherits tax from the agreement.
                         * @example true
                         */
                        inheritTaxFromAgreement?: boolean;
                        /**
                         * @description Indicates if the product is active.
                         * @example true
                         */
                        active?: boolean;
                    }[];
                };
            };
            /** @description Permission denied */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": unknown;
                };
            };
        };
    };
