    getDeviceGeolocationHistory: {
        parameters: {
            query?: {
                /** @description Include records on or after this timestamp (epoch seconds). Defaults to 7 days ago. */
                after?: number;
                /** @description Include records on or before this timestamp (epoch seconds). Defaults to now. */
                before?: number;
                /** @description Limit number of records per page */
                pageSize?: number;
                /** @description Cursor name */
                cursor?: string;
            };
            header?: never;
            path: {
                /** @description Device identifier */
                id: number;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Geolocation history */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Geolocation records */
                        results?: {
                            /**
                             * Format: double
                             * @description Device latitude
                             * @example 28.260770164828532
                             */
                            latitude?: number;
                            /**
                             * Format: double
                             * @description Device longitude
                             * @example -82.18508102335356
                             */
                            longitude?: number;
                            /**
                             * Format: double
                             * @description Location timestamp, epoch seconds with millisecond precision
                             * @example 1778938364.507
                             */
                            timestamp?: number;
                        }[];
                        cursor?: {
                            name?: string;
                            /** Format: int32 */
                            offset?: number;
                            /** Format: int32 */
                            count?: number;
                            /** Format: double */
                            expires?: number;
                        };
                    };
                };
            };
            /** @description Invalid parameters or cursor */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Unauthorized */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Forbidden */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Device not found or not a mobile device */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Rate limit exceeded */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
